--
-- Table structure for table `procurement_plans`
--

CREATE TABLE `procurement_plans` (
  `id` varchar(36) NOT NULL,
  `idx` int(11) DEFAULT NULL,
  `code` varchar(191) DEFAULT NULL,
  `name` text DEFAULT NULL,
  `type` varchar(100) DEFAULT NULL,
  `budget_cost` decimal(15,2) NOT NULL DEFAULT 0.00,
  `year_financing` decimal(15,2) NOT NULL DEFAULT 0.00,
  `tender_method` varchar(255) DEFAULT NULL,
  `tender_month` varchar(255) DEFAULT NULL,
  `sustainable` varchar(100) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `project_name` varchar(255) DEFAULT NULL,
  `implement_period` varchar(255) DEFAULT NULL,
  `committee_formed` varchar(255) DEFAULT NULL,
  `advertised` varchar(255) DEFAULT NULL,
  `tender_opened` varchar(255) DEFAULT NULL,
  `committee_met` varchar(255) DEFAULT NULL,
  `notice_sent` varchar(255) DEFAULT NULL,
  `contract_signed` varchar(255) DEFAULT NULL,
  `contract_value` decimal(15,2) NOT NULL DEFAULT 0.00,
  `payment1` decimal(15,2) NOT NULL DEFAULT 0.00,
  `payment2` decimal(15,2) NOT NULL DEFAULT 0.00,
  `payment3` decimal(15,2) NOT NULL DEFAULT 0.00,
  `variance` varchar(255) DEFAULT NULL,
  `extra_notes` text DEFAULT NULL,
  `visible_to_user_ids` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`visible_to_user_ids`)),
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

