-- ===== Шинэ хүснэгтүүд =====

-- Хурлын тэмдэглэл
CREATE TABLE IF NOT EXISTS `meeting_minutes` (
  `id` VARCHAR(36) NOT NULL,
  `title` VARCHAR(255) NOT NULL,
  `date` DATE NOT NULL,
  `time` VARCHAR(5) NULL,
  `attendee_user_ids` JSON DEFAULT NULL,
  `agenda` TEXT DEFAULT NULL,
  `decisions` TEXT DEFAULT NULL,
  `notes` TEXT DEFAULT NULL,
  `attachments` JSON DEFAULT NULL,
  `visible_to_user_ids` JSON DEFAULT NULL,
  `created_by` VARCHAR(36) NULL,
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Ээлжийн амралтын хүсэлт
CREATE TABLE IF NOT EXISTS `leave_requests` (
  `id` VARCHAR(36) NOT NULL,
  `user_id` VARCHAR(36) NOT NULL,
  `user_name` VARCHAR(255) NOT NULL,
  `start_date` DATE NOT NULL,
  `end_date` DATE NOT NULL,
  `days` INT NOT NULL DEFAULT 0,
  `reason` TEXT DEFAULT NULL,
  `status` ENUM('Pending','Approved','Rejected') NOT NULL DEFAULT 'Pending',
  `year` INT NOT NULL,
  `reviewed_by` VARCHAR(36) NULL,
  `reviewed_by_name` VARCHAR(255) NULL,
  `reviewed_at` TIMESTAMP NULL,
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_leave_user_year` (`user_id`,`year`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Жилийн амралтын глобал эрх
CREATE TABLE IF NOT EXISTS `leave_settings` (
  `year` INT NOT NULL,
  `days` INT NOT NULL DEFAULT 15,
  `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`year`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Ажилтан тус бүрийн амралтын хоног (override)
CREATE TABLE IF NOT EXISTS `leave_entitlements` (
  `user_id` VARCHAR(36) NOT NULL,
  `year` INT NOT NULL,
  `days` INT NOT NULL,
  `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`user_id`,`year`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Хурал эхэлсэн дохио
CREATE TABLE IF NOT EXISTS `meeting_signals` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `meeting_id` VARCHAR(36) NULL,
  `title` VARCHAR(255) NOT NULL,
  `meeting_time` VARCHAR(5) NULL,
  `started_by` VARCHAR(36) NULL,
  `started_by_name` VARCHAR(255) NULL,
  `started_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `ended_at` TIMESTAMP NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Ажилчид хоорондын зурвас
CREATE TABLE IF NOT EXISTS `messages` (
  `id` VARCHAR(36) NOT NULL,
  `sender_id` VARCHAR(36) NOT NULL,
  `recipient_id` VARCHAR(36) NOT NULL,
  `content` MEDIUMTEXT DEFAULT NULL,
  `attachments` JSON DEFAULT NULL,
  `read_at` TIMESTAMP NULL,
  `created_at` TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `idx_msg_recipient` (`recipient_id`),
  KEY `idx_msg_pair` (`sender_id`,`recipient_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Ажилтны хувийн хурлын тэмдэглэл
CREATE TABLE IF NOT EXISTS `personal_meeting_notes` (
  `id` VARCHAR(36) NOT NULL,
  `user_id` VARCHAR(36) NOT NULL,
  `meeting_id` VARCHAR(36) NULL,
  `meeting_title` VARCHAR(255) NOT NULL,
  `meeting_date` DATE NULL,
  `notes` MEDIUMTEXT DEFAULT NULL,
  `director_tasks` MEDIUMTEXT DEFAULT NULL,
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_personal_notes_user` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

